      initialCode: 'import numpy as np\nfrom sklearn.linear_model import LinearRegression\nfrom sklearn.preprocessing import PolynomialFeatures\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.metrics import mean_squared_error\n\nnp.random.seed(42)\n\n# Data: y = sin(x) + noise\nX = np.sort(np.random.uniform(0, 6, 50)).reshape(-1, 1)\ny = np.sin(X.ravel()) + np.random.randn(50) * 0.2\n\nX_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.3, random_state=42)\n\nprint("Degree | Train MSE | Test MSE  | Status")\nprint("-------|-----------|-----------|-------")\n\nfor degree in [1, 2, 3, 5, 10, 15]:\n    poly = PolynomialFeatures(degree)\n    X_train_p = poly.fit_transform(X_train)\n    X_test_p = poly.transform(X_test)\n    \n    model = LinearRegression()\n    model.fit(X_train_p, y_train)\n    \n    train_mse = mean_squared_error(y_train, model.predict(X_train_p))\n    test_mse = mean_squared_error(y_test, model.predict(X_test_p))\n    \n    gap = test_mse - train_mse\n    if degree <= 2:\n        status = "Underfit"\n    elif gap > 0.5:\n        status = "OVERFIT ⚠️"\n    else:\n        status = "Good ✅"\n    \n    print(f"  {degree:4d}  | {train_mse:9.4f} | {test_mse:9.4f} | {status}")',
