      initialCode: 'import numpy as np\nimport re\nfrom collections import Counter\n\ndef tokenize(text):\n    return re.findall(r"\\w+", text.lower())\n\ncorpus = [\n    "machine learning adalah teknik AI",\n    "deep learning bagian dari machine learning",\n    "neural network digunakan dalam deep learning",\n    "AI menggunakan machine learning dan deep learning",\n]\n\n# Build vocab\nall_tokens = set()\nfor doc in corpus:\n    all_tokens.update(tokenize(doc))\nvocab = sorted(all_tokens)\n\n# TF: term frequency per document\ndef compute_tf(doc, vocab):\n    tokens = tokenize(doc)\n    counts = Counter(tokens)\n    total = len(tokens)\n    return [counts.get(w, 0) / total for w in vocab]\n\n# IDF: inverse document frequency\ndef compute_idf(corpus, vocab):\n    n_docs = len(corpus)\n    idf = []\n    for word in vocab:\n        doc_count = sum(1 for doc in corpus if word in tokenize(doc))\n        idf.append(np.log(n_docs / (1 + doc_count)) + 1)\n    return idf\n\nidf = compute_idf(corpus, vocab)\n\n# TF-IDF\nprint("TF-IDF Scores (top words per document):\\n")\nfor i, doc in enumerate(corpus):\n    tf = compute_tf(doc, vocab)\n    tfidf = [t * i for t, i in zip(tf, idf)]\n    \n    # Sort by score\n    word_scores = sorted(zip(vocab, tfidf), key=lambda x: -x[1])\n    top_words = [(w, s) for w, s in word_scores if s > 0][:5]\n    \n    print(f"Doc {i+1}: \\"{doc}\\"") \n    for word, score in top_words:\n        print(f"  {word:15s} {score:.4f}")\n    print()',
