      initialCode: 'import time\nfrom collections import deque\n\nclass RateLimiter:\n    def __init__(self, max_requests, time_window):\n        """\n        max_requests: jumlah max request dalam time_window\n        time_window: window dalam detik\n        """\n        self.max_requests = max_requests\n        self.time_window = time_window\n        self.requests = deque()\n    \n    def allow_request(self):\n        current_time = time.time()\n        \n        # Buang request yang sudah di luar window\n        while self.requests and self.requests[0] < current_time - self.time_window:\n            self.requests.popleft()\n        \n        if len(self.requests) < self.max_requests:\n            self.requests.append(current_time)\n            return True\n        return False\n    \n    def status(self):\n        current_time = time.time()\n        while self.requests and self.requests[0] < current_time - self.time_window:\n            self.requests.popleft()\n        return f"{len(self.requests)}/{self.max_requests} requests used"\n\n# Test: max 5 requests per 2 detik\nlimiter = RateLimiter(max_requests=5, time_window=2.0)\n\nprint("Simulasi 8 API calls:")\nfor i in range(8):\n    allowed = limiter.allow_request()\n    status = "✅ Allowed" if allowed else "❌ Rate limited"\n    print(f"  Request {i+1}: {status} ({limiter.status()})")\n\nprint(f"\\nRate Limiter config: {limiter.max_requests} req / {limiter.time_window}s")',
